static NSHashTable<AVPlayerItem *> *Players(){static NSHashTable *items;static dispatch_once_t once;dispatch_once(&once,^{items=[NSHashTable weakObjectsHashTable];});return items;}
static std::array<double,3> HSL(double h,double s,double l){h=h-floor(h);double c=(1-fabs(2*l-1))*s,x=c*(1-fabs(fmod(h*6,2)-1)),m=l-c/2;std::array<double,3> rgb;if(h<1./6)rgb={c,x,0};else if(h<2./6)rgb={x,c,0};else if(h<3./6)rgb={0,c,x};else if(h<4./6)rgb={0,x,c};else if(h<5./6)rgb={x,0,c};else rgb={c,0,x};for(double &v:rgb)v+=m;return rgb;}
static NSData *Cube(NSDictionary *values){const int n=32;NSMutableData *data=[NSMutableData dataWithLength:n*n*n*4*sizeof(float)];float *out=(float *)data.mutableBytes;NSArray *names=@[@"red",@"orange",@"yellow",@"green",@"cyan",@"blue",@"purple",@"magenta"];const double centers[]={0,1./12,1./6,1./3,.5,2./3,.75,5./6};double hue[8],sat[8],light[8];for(int i=0;i<8;i++){hue[i]=V(values,[names[i]stringByAppendingString:@".h"])/360;sat[i]=V(values,[names[i]stringByAppendingString:@".s"])/100;light[i]=V(values,[names[i]stringByAppendingString:@".l"])/100;}
 std::array<double,3> wheels[3];double strengths[3];NSArray *wheelNames=@[@"shadow",@"mid",@"highlight"];for(int i=0;i<3;i++){wheels[i]=HSL(V(values,[wheelNames[i]stringByAppendingString:@".hue"])/360,1,.5);strengths[i]=V(values,[wheelNames[i]stringByAppendingString:@".strength"])/100;}
 for(int b=0;b<n;b++)for(int g=0;g<n;g++)for(int r=0;r<n;r++){double red=r/double(n-1),green=g/double(n-1),blue=b/double(n-1),maximum=std::max({red,green,blue}),minimum=std::min({red,green,blue}),delta=maximum-minimum,l=(maximum+minimum)/2,s=delta<1e-8?0:delta/(1-fabs(2*l-1)),h=0;if(delta>1e-8){if(maximum==red)h=fmod((green-blue)/delta+6,6)/6;else if(maximum==green)h=((blue-red)/delta+2)/6;else h=((red-green)/delta+4)/6;}double dh=0,ds=0,dl=0,weight=0;for(int i=0;i<8;i++){double distance=fabs(h-centers[i]);distance=std::min(distance,1-distance);double w=std::max(0.,1-distance/.16);dh+=hue[i]*w;ds+=sat[i]*w;dl+=light[i]*w;weight+=w;}if(weight>0){h+=dh/weight;s=std::clamp(s*(1+ds/weight),0.,1.);l=std::clamp(l+dl/weight*.5,0.,1.);}auto rgb=HSL(h,s,l);double luminance=.2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2],balance=V(values,@"wheel.balance")/200;double sh=std::clamp(1-(luminance+balance)*2,0.,1.),hi=std::clamp((luminance+balance)*2-1,0.,1.),weights[]={sh,1-sh-hi,hi};for(int channel=0;channel<3;channel++){double v=rgb[channel]+V(values,@"whites")/100*.35*pow(luminance,3)+V(values,@"blacks")/100*.35*pow(1-luminance,3);for(int i=0;i<3;i++)v+=(wheels[i][channel]-.5)*strengths[i]*weights[i]*.45;*out++=std::clamp(v,0.,1.);}*out++=1;}return data;}
static CIImage *Filtered(CIImage *source,DGColorState *state){if(!state.enabled)return source;NSDictionary *v=state.values;CIImage *image=source;auto filter=[&](NSString *name,NSDictionary *inputs){NSMutableDictionary *parameters=[inputs mutableCopy];parameters[kCIInputImageKey]=image;CIImage *output=[CIFilter filterWithName:name withInputParameters:parameters].outputImage;if(output)image=output;};
 filter(@"CIExposureAdjust",@{kCIInputEVKey:@(V(v,@"exposure"))});filter(@"CIHighlightShadowAdjust",@{@"inputHighlightAmount":@(1-V(v,@"highlights")/100),@"inputShadowAmount":@(V(v,@"shadows")/100)});filter(@"CIColorControls",@{kCIInputContrastKey:@(1+V(v,@"contrast")/100),kCIInputSaturationKey:@(1+V(v,@"saturation")/100)});filter(@"CIVibrance",@{@"inputAmount":@(V(v,@"vibrance")/100)});filter(@"CITemperatureAndTint",@{@"inputNeutral":[CIVector vectorWithX:6500 Y:0],@"inputTargetNeutral":[CIVector vectorWithX:6500+V(v,@"temperature")*40 Y:V(v,@"tint")]});
