static DGColorState *Snapshot(){std::lock_guard<std::mutex> lock(Guard);return Current;}
static void Configure(AVPlayerItem *item){item.appliesPerFrameHDRDisplayMetadata=[NSUserDefaults.standardUserDefaults boolForKey:@"douglass.hdr"];DGColorState *state=Snapshot();if(!state.enabled){item.videoComposition=nil;return;}__weak AVPlayerItem *weak=item;[item.asset loadTracksWithMediaType:AVMediaTypeVideo completionHandler:^(NSArray<AVAssetTrack *> *tracks,NSError *error){dispatch_async(dispatch_get_main_queue(),^{AVPlayerItem *item=weak;if(!item||!tracks.count||!Snapshot().enabled)return;if([NSUserDefaults.standardUserDefaults boolForKey:@"douglass.hdr"]){for(AVAssetTrack *track in tracks)if([track hasMediaCharacteristic:AVMediaCharacteristicContainsHDRVideo]){item.videoComposition=nil;return;}}item.videoComposition=[AVVideoComposition videoCompositionWithAsset:item.asset applyingCIFiltersWithHandler:^(AVAsynchronousCIImageFilteringRequest *request){DGColorState *current=Snapshot();[request finishWithImage:Filtered(request.sourceImage,current) context:nil];}];});}];}
void DGColorConfigure(AVPlayerItem *item){if(!item)return;[Players()addObject:item];static dispatch_once_t once;dispatch_once(&once,^{DGColorReload();});Configure(item);}
void DGColorReload(void){NSUInteger generation=++Generation;NSDictionary *values=Settings();BOOL enabled=[NSUserDefaults.standardUserDefaults boolForKey:@"douglass.color.enabled"];dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{DGColorState *state=[DGColorState new];state.values=values;state.enabled=enabled;state.cube=enabled?Cube(values):nil;dispatch_async(dispatch_get_main_queue(),^{if(generation!=Generation)return;BOOL before=Snapshot().enabled;BOOL hdr=[NSUserDefaults.standardUserDefaults boolForKey:@"douglass.hdr"],hdrChanged=hdr!=LastHDR;LastHDR=hdr;{std::lock_guard<std::mutex> lock(Guard);Current=state;}for(AVPlayerItem *item in Players().allObjects)if(before!=enabled||hdrChanged)Configure(item);[NSNotificationCenter.defaultCenter postNotificationName:@"DGColorChanged" object:nil];});});}
UIImage *DGColorImage(UIImage *image){DGColorState *state=Snapshot();if(!state.enabled||!image.CGImage||([NSUserDefaults.standardUserDefaults boolForKey:@"douglass.hdr"]&&image.isHighDynamicRange))return image;CIImage *source=[[CIImage alloc]initWithCGImage:image.CGImage];CIImage *output=Filtered(source,state);static CIContext *context;static dispatch_once_t once;dispatch_once(&once,^{context=[CIContext contextWithOptions:@{kCIContextUseSoftwareRenderer:@NO}];});CGImageRef frame=[context createCGImage:output fromRect:source.extent];if(!frame)return image;UIImage *result=[UIImage imageWithCGImage:frame scale:image.scale orientation:image.imageOrientation];CGImageRelease(frame);return result;}

static NSDictionary *Control(NSString *key,NSString *label,double min,double max,double initial=0){return @{@"key":key,@"label":label,@"min":@(min),@"max":@(max),@"initial":@(initial)};}
@interface DGColorSettings:UITableViewController
@property(nonatomic,copy) NSString *previewURL;
@end
@implementation DGColorSettings{NSArray *_groups;DGImage *_preview;UILabel *_previewLabel;BOOL _showOriginal;}
- (void)viewDidLoad{[super viewDidLoad];self.title=@"视频与图文调色";self.navigationItem.leftBarButtonItem=[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemClose target:self action:@selector(close)];self.tableView.rowHeight=62;UIView *header=[[UIView alloc]initWithFrame:CGRectMake(0,0,self.view.bounds.size.width,248)];_preview=[DGImage new];_preview.maximumPixelSize=720;_preview.colorAdjusted=YES;_preview.backgroundColor=UIColor.blackColor;_preview.contentMode=UIViewContentModeScaleAspectFit;_preview.layer.cornerRadius=16;_preview.clipsToBounds=YES;_preview.userInteractionEnabled=YES;[_preview addGestureRecognizer:[[UITapGestureRecognizer alloc]initWithTarget:self action:@selector(compare)]];[header addSubview:_preview];_previewLabel=Label(12,UIFontWeightMedium);_previewLabel.textColor=UIColor.secondaryLabelColor;_previewLabel.textAlignment=NSTextAlignmentCenter;_previewLabel.numberOfLines=2;[header addSubview:_previewLabel];self.tableView.tableHeaderView=header;[_preview remote:self.previewURL?:@""];[self previewText];self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithTitle:@"预设" style:UIBarButtonItemStylePlain target:self action:@selector(presets)];NSMutableArray *curve=[NSMutableArray array];for(int i=0;i<5;i++){[curve addObject:Control([NSString stringWithFormat:@"curve.%d.x",i],[NSString stringWithFormat:@"点 %d · 输入 X",i+1],0,1,i/4.)];[curve addObject:Control([NSString stringWithFormat:@"curve.%d.y",i],[NSString stringWithFormat:@"点 %d · 输出 Y",i+1],0,1,i/4.)];}NSMutableArray *hsl=[NSMutableArray array];NSArray *keys=@[@"red",@"orange",@"yellow",@"green",@"cyan",@"blue",@"purple",@"magenta"],*labels=@[@"红",@"橙",@"黄",@"绿",@"青",@"蓝",@"紫",@"洋红"];for(NSUInteger i=0;i<keys.count;i++){[hsl addObject:Control([keys[i]stringByAppendingString:@".h"],[labels[i]stringByAppendingString:@" · 色相"],-180,180)];[hsl addObject:Control([keys[i]stringByAppendingString:@".s"],[labels[i]stringByAppendingString:@" · 饱和度"],-100,100)];[hsl addObject:Control([keys[i]stringByAppendingString:@".l"],[labels[i]stringByAppendingString:@" · 明度"],-100,100)];}_groups=@[@[],@[Control(@"exposure",@"曝光 EV",-5,5),Control(@"texture",@"质感",-100,100),Control(@"sharpen",@"锐化",0,100),Control(@"contrast",@"对比度",-100,100),Control(@"highlights",@"高光",-100,100),Control(@"shadows",@"阴影",-100,100),Control(@"whites",@"白色色阶",-100,100),Control(@"blacks",@"黑色色阶",-100,100),Control(@"temperature",@"色温",-100,100),Control(@"tint",@"色调",-100,100),Control(@"saturation",@"饱和度",-100,100),Control(@"vibrance",@"自然饱和度",-100,100)],curve,hsl,@[Control(@"shadow.hue",@"阴影色轮 · 色相",0,360),Control(@"shadow.strength",@"阴影色轮 · 强度",0,100),Control(@"mid.hue",@"中间调色轮 · 色相",0,360),Control(@"mid.strength",@"中间调色轮 · 强度",0,100),Control(@"highlight.hue",@"高光色轮 · 色相",0,360),Control(@"highlight.strength",@"高光色轮 · 强度",0,100),Control(@"wheel.balance",@"分离色调 · 平衡",-100,100)]];}
- (void)viewDidLayoutSubviews{[super viewDidLayoutSubviews];CGFloat w=self.tableView.bounds.size.width;_preview.frame=CGRectMake(16,8,w-32,200);_previewLabel.frame=CGRectMake(16,211,w-32,34);}
- (void)previewText{_previewLabel.text=!self.previewURL.length?@"当前作品没有可用的封面预览":_showOriginal?@"原始封面 · 点击查看调色后效果":@"当前作品封面预览 · 点击对比原图";}
- (void)compare{_showOriginal=!_showOriginal;_preview.colorAdjusted=!_showOriginal;[self previewText];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)table{return _groups.count;}
- (NSInteger)tableView:(UITableView *)table numberOfRowsInSection:(NSInteger)section{return section==0?1:Array(_groups[section]).count;}
- (NSString *)tableView:(UITableView *)table titleForHeaderInSection:(NSInteger)section{return @[@"全局开关",@"基础",@"自定义曲线",@"HSL",@"色轮／分离色调"][section];}
- (NSString *)tableView:(UITableView *)table titleForFooterInSection:(NSInteger)section{return section==0?@"预览使用当前作品封面。开启源 HDR 时，实际 HDR 素材优先保留原始动态范围，跳过 SDR 调色；保存的原文件不变。":section==2?@"X 需从小到大，Y 为对应输出亮度。":nil;}
- (UITableViewCell *)tableView:(UITableView *)table cellForRowAtIndexPath:(NSIndexPath *)path{UITableViewCell *cell=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleValue1 reuseIdentifier:nil];if(path.section==0){cell.textLabel.text=@"启用调色";UISwitch *toggle=[UISwitch new];toggle.on=[NSUserDefaults.standardUserDefaults boolForKey:@"douglass.color.enabled"];[toggle addTarget:self action:@selector(toggle:) forControlEvents:UIControlEventValueChanged];cell.accessoryView=toggle;}else{NSDictionary *row=_groups[path.section][path.row];cell.textLabel.text=row[@"label"];cell.detailTextLabel.text=[NSString stringWithFormat:@"%.3f",V(Settings(),row[@"key"],[row[@"initial"]doubleValue])];cell.accessoryType=UITableViewCellAccessoryDisclosureIndicator;}return cell;}
- (void)close{[self dismissViewControllerAnimated:YES completion:^{[NSNotificationCenter.defaultCenter postNotificationName:@"DGResumePlayback" object:nil];}];}
- (void)toggle:(UISwitch *)toggle{[NSUserDefaults.standardUserDefaults setBool:toggle.on forKey:@"douglass.color.enabled"];DGColorReload();}
- (void)tableView:(UITableView *)table didSelectRowAtIndexPath:(NSIndexPath *)path{[table deselectRowAtIndexPath:path animated:YES];if(path.section==0)return;NSDictionary *row=_groups[path.section][path.row];UIAlertController *alert=[UIAlertController alertControllerWithTitle:row[@"label"] message:[NSString stringWithFormat:@"范围 %@ ～ %@",row[@"min"],row[@"max"]] preferredStyle:UIAlertControllerStyleAlert];[alert addTextFieldWithConfigurationHandler:^(UITextField *field){field.keyboardType=UIKeyboardTypeNumbersAndPunctuation;field.text=[NSString stringWithFormat:@"%.3f",V(Settings(),row[@"key"],[row[@"initial"]doubleValue])];}];[alert addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[alert addAction:[UIAlertAction actionWithTitle:@"应用" style:UIAlertActionStyleDefault handler:^(UIAlertAction *action){NSScanner *scanner=[NSScanner scannerWithString:alert.textFields.firstObject.text];double value;if(![scanner scanDouble:&value]||!scanner.isAtEnd||!std::isfinite(value)||value<[row[@"min"]doubleValue]||value>[row[@"max"]doubleValue]){DGToast(self,@"输入数值无效");return;}NSMutableDictionary *values=[Settings()mutableCopy];values[row[@"key"]]=@(value);if([row[@"key"]hasPrefix:@"curve."]){for(int i=1;i<5;i++)if(V(values,[NSString stringWithFormat:@"curve.%d.x",i],i/4.)<=V(values,[NSString stringWithFormat:@"curve.%d.x",i-1],(i-1)/4.)){DGToast(self,@"曲线 X 坐标需要从小到大");return;}}[NSUserDefaults.standardUserDefaults setObject:values forKey:@"douglass.color.values"];[NSUserDefaults.standardUserDefaults setBool:YES forKey:@"douglass.color.enabled"];DGColorReload();[self.tableView reloadData];}]];[self presentViewController:alert animated:YES completion:nil];}
